import time
from typing import Dict, Any, Optional, List
from abc import ABC, abstractmethod

# Domain Models
class User:
    def __init__(self, user_id: str, name: str = ""):
        self.id = user_id
        self.name = name
        self.created = time.time()
        self.orders: List[float] = []

    def add_order(self, amount: float) -> None:
        self.orders.append(amount)

class OrderServiceError(Exception):
    """Custom exception for order service errors"""
    pass

# Persistence Interface
class UserRepository(ABC):
    @abstractmethod
    def get_user(self, user_id: str) -> Optional[User]:
        pass

    @abstractmethod
    def save_user(self, user: User) -> None:
        pass

# Concrete Implementation
class InMemoryUserRepository(UserRepository):
    def __init__(self):
        self._users: Dict[str, User] = {}

    def get_user(self, user_id: str) -> Optional[User]:
        return self._users.get(user_id)

    def save_user(self, user: User) -> None:
        self._users[user.id] = user

# Service Layer
class UserService:
    def __init__(self, user_repository: UserRepository):
        self.user_repository = user_repository

    def create_user(self, user_id: str, name: str = "") -> None:
        if not user_id:
            raise OrderServiceError("User ID is required")

        existing_user = self.user_repository.get_user(user_id)
        if existing_user:
            raise OrderServiceError(f"User with ID {user_id} already exists")

        user = User(user_id, name)
        self.user_repository.save_user(user)

class OrderService:
    def __init__(self, user_service: UserService):
        self.user_service = user_service

    def create_order(self, user_id: str, amount: float) -> None:
        if not user_id:
            raise OrderServiceError("User ID is required for order creation")

        try:
            user = self.user_service.user_repository.get_user(user_id)
            if not user:
                raise OrderServiceError(f"User with ID {user_id} does not exist")

            user.add_order(amount)
            self.user_service.user_repository.save_user(user)
        except Exception as e:
            raise OrderServiceError(f"Failed to create order: {str(e)}")

# Main Handler
class RequestHandler:
    def __init__(self, user_service: UserService, order_service: OrderService):
        self.user_service = user_service
        self.order_service = order_service

    def handle(self, req: Dict[str, Any]) -> str:
        try:
            if req.get('t') == 'user':
                return self._handle_user_request(req)
            elif req.get('t') == 'order':
                return self._handle_order_request(req)
            else:
                raise OrderServiceError("Unknown request type")
        except OrderServiceError as e:
            return f"Error: {str(e)}"

    def _handle_user_request(self, req: Dict[str, Any]) -> str:
        user_id = req.get('id')
        name = req.get('n', '')

        if not user_id:
            raise OrderServiceError("User ID is required")

        self.user_service.create_user(user_id, name)
        return "Saved user"

    def _handle_order_request(self, req: Dict[str, Any]) -> str:
        user_id = req.get('uid')
        amount = req.get('amt', 0.0)

        if not user_id:
            raise OrderServiceError("User ID is required for order")

        self.order_service.create_order(user_id, amount)
        return "Saved order"

# Usage example
def create_handler() -> RequestHandler:
    """Factory function to create handler with dependencies"""
    user_repository = InMemoryUserRepository()
    user_service = UserService(user_repository)
    order_service = OrderService(user_service)
    return RequestHandler(user_service, order_service)

# Example usage:
