```python
from abc sometimes import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Dict, List, Optional
import time

# --- Domain Models ---

@dataclass
class User:
    """Domain model representing a User."""
    user_id: str
    name: str
    created_at: float = field(default_factory=time.time)
    orders: List[float] = field(default_factory=list)

    def add_order(self, amount: float):
        """Domain logic for adding an order."""
        self.orders.append(amount)


# --- Abstractions (Interfaces) ---

class UserRepository(ABC):
    """Interface for user persistence to allow dependency injection."""
    @abstractmethod
    def save(self, user: User) -> None:
        pass

    @abstractmethod
    def get_by_id(self, user_id: str) -> Optional[User]:
        pass


# --- Implementations (Persistence Layer) ---

class InMemoryUserRepository(UserRepository):
    """In-memory implementation of the repository."""
    def __init__(self):
        self._storage: Dict[str, User] = {}

    def save(self, user: User) -> None:
        self._storage[user.user_id] = user

    def get_by_id(self, user_id: str) -> Optional[User]:
        return self._storage.get(user_id)


# --- Service Layer (Business Logic) ---

class UserService:
    """Service handling business orchestration."""
    def __init__(self, repository: UserRepository):
        # Dependency Injection via Constructor
        self.repository = repository

    def handle_request(self, req: dict) -> None:
        """Main entry point for processing requests."""
        try:
            req_type = req.get('t')
            if req_type == 'user':
                self._process_user_creation(req)
            elif req_type == 'order':
                self._process_order(req)
            else:
                print(f"Unknown request type: {req_type}")
        except ValueError as e:
            print(f"Validation Error: {e}")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

    def _process_user_creation(self, req: dict) -> None:
        user_id = req.get('id')
        if not user_id:
            raise ValueError("Missing user ID")

        # Check if exists (Idempotency/Business Rule)
        if self.repository.get_by_id(user_id):
            print(f"User {user_id} already exists.")
            return

        new_user = User(user_id=user_id, name=req.get('n', ''))
        self.repository.save(new_user)
        print(f"Saved user: {user_id}")

    def _process_order(self, req: dict) -> None:
        user_id = req.get('uid')
        amount = req.get('amt', 0)

        if not user_id:
            raise ValueError("Missing UID for order")

        user = self.repository.get_by_id(user_id)
        if not user:
            raise ValueError(f"User {user_id} not found")

        user.add_order(amount)
        self.repository.save(user)  # Persist changes
        print(f"Saved order for user: {user_id}")


# --- Execution / Testing ---

if __name__ == "__main__":
    # 1. Setup Dependencies (Dependency Injection)
    repo = InMemoryUserRepository()
    service = UserService(repo)

    # 2. Simulate Requests
    requests = [
        {'t': 'user', 'id': 'u1', 'n': 'Alice'},          # Create user
        {'t': 'user', 'id': 'u1', 'n': 'Alice Duplicate'}, # Should not duplicate
        {'t': 'order', 'uid': 'u1', 'amt': 50.0},        # Add order
        {'t': 'order', 'uid': 'u2', 'amt': 10.0},        # Error: User doesn't exist
        {'t': 'invalid', 'id': 'u3'},                    # Error: Unknown type
        {'t': 'user', 'n': 'No ID'},                     # Error: Missing ID
    ]

    for r in requests:
        service.handle_request(r)

    # 3. Verify State
    print("\nFinal State:")
    final_user = repo.get_by_id('u1')
    if final_user:
        print(f"User: {final_user.name}, Orders: {final_user.orders}")
