from abc import ABC, abstractmethod
import time
from typing import Any, Dict, Optional


class PersistenceError(Exception):
    """Raised when a persistence operation fails."""
    pass


class DomainError(Exception):
    """Raised when a domain rule is violated."""
    pass


# --- Domain Models ---

class User:
    def __init__(self, user_id: str, name: str = '', created: Optional[float] = None):
        self.user_id = user_id
        self.name = name
        self.created = created if created is not None else time.time()
        self.orders: list[float] = []

    def add_order(self, amount: float) -> None:
        self.orders.append(amount)


# --- Persistence Layer (Abstraction) ---

class UserPersistence(ABC):
    @abstractmethod
    def save_user(self, user: User) -> None:
        """Persist a new user. Raises PersistenceError on failure."""
        pass

    @abstractmethod
    def get_user(self, user_id: str) -> Optional[User]:
        """Retrieve a user by ID. Returns None if not found."""
        pass


class InMemoryUserPersistence(UserPersistence):
    def __init__(self):
        self._store: Dict[str, User] = {}

    def save_user(self, user: User) -> None:
        try:
            if user.user_id in self._store:
                raise PersistenceError(f"User {user.user_id} already exists")
            self._store[user.user_id] = user
        except Exception as e:
            raise PersistenceError(f"Failed to save user: {e}") from e

    def get_user(self, user_id: str) -> Optional[User]:
        return self._store.get(user_id)


# --- Service Layer (Business Logic) ---

class UserService(ABC):
    @abstractmethod
    def create_user(self, user_id: str, name: str = '') -> User:
        """Create and persist a new user."""
        pass

    @abstractmethod
    def add_order_to_user(self, user_id: str, amount: float) -> None:
        """Add an order to an existing user."""
        pass


class UserServiceImpl(UserService):
    def __init__(self, persistence: UserPersistence):
        self._persistence = persistence

    def create_user(self, user_id: str, name: str = '') -> User:
        if not user_id:
            raise DomainError("User ID cannot be empty")

        existing = self._persistence.get_user(user_id)
        if existing is not None:
            raise DomainError(f"User {user_id} already exists")

        user = User(user_id=user_id, name=name)
        try:
            self._persistence.save_user(user)
        except PersistenceError as e:
            raise DomainError(f"Failed to create user: {e}") from e
        return user

    def add_order_to_user(self, user_id: str, amount: float) -> None:
        if not user_id:
            raise DomainError("User ID cannot be empty")

        user = self._persistence.get_user(user_id)
        if user is None:
            raise DomainError(f"User {user_id} does not exist")

        try:
            user.add_order(amount)
        except Exception as e:
            raise DomainError(f"Failed to add order: {e}") from e


# --- Request Handler (Facade / Application Layer) ---

class RequestHandler:
    def __init__(self, user_service: UserService):
        self._user_service = user_service

    def handle(self, req: Dict[str, Any]) -> str:
        """
        Handle an incoming request dictionary.

        Expected keys:
          - 't': type of request ('user' or 'order')
          For 'user':
            - 'id': user ID (required)
            - 'n': name (optional, defaults to '')
          For 'order':
            - 'uid': user ID (required)
            - 'amt': order amount (optional, defaults to 0.0)

        Returns a status message string.
        Raises DomainError or PersistenceError on failure.
        """
        req_type = req.get('t')

        if req_type == 'user':
            user_id = req.get('id')
            name = req.get('n', '')
            self._user_service.create_user(user_id, name)
            return "Saved user"

        elif req_type == 'order':
            uid = req.get('uid')
            amt = float(req.get('amt', 0.0))
            self._user_service.add_order_to_user(uid, amt)
            return "Saved order"

        else:
            raise DomainError(f"Unknown request type: {req_type}")


# --- Factory / Composition Root (Dependency Injection) ---

def create_request_handler(persistence: Optional[UserPersistence] = None) -> RequestHandler:
    """
    Create a fully wired RequestHandler with default dependencies.

    Args:
        persistence: A UserPersistence instance. If None, an InMemoryUserPersistence is used.

    Returns:
        A configured RequestHandler ready to process requests.
    """
    if persistence is None:
        persistence = InMemoryUserPersistence()

    user_service = UserServiceImpl(persistence)
    return RequestHandler(user_service)


# --- Example Usage / Test ---

if __name__ == "__main__":
    handler = create_request_handler()

    # Create a user
    result = handler.handle({'t': 'user', 'id': 'u1', 'n': 'Alice'})
    print(result)  # "Saved user"

    # Add an order to the user
