import time
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Dict, List, Optional


# --- Domain Models ---

@dataclass
class User:
    id: str
    name: str = ""
    created: float = field(default_factory=time.time)


@dataclass
class Order:
    amount: float = 0.0


# --- Persistence Layer (Repository Pattern) ---

class UserRepository(ABC):
    @abstractmethod
    def get_user(self, user_id: str) -> Optional[User]:
        ...

    @abstractmethod
    def save_user(self, user: User) -> None:
        ...


class InMemoryUserRepository(UserRepository):
    def __init__(self) -> None:
        self._users: Dict[str, User] = {}

    def get_user(self, user_id: str) -> Optional[User]:
        return self._users.get(user_id)

    def save_user(self, user: User) -> None:
        self._users[user.id] = user


class OrderRepository(ABC):
    @abstractmethod
    def add_order(self, user_id: str, order: Order) -> None:
        ...


class InMemoryOrderRepository(OrderRepository):
    def __init__(self) -> None:
        self._orders: Dict[str, List[Order]] = {}

    def add_order(self, user_id: str, order: Order) -> None:
        if user_id not in self._orders:
            self._orders[user_id] = []
        self._orders[user_id].append(order)


# --- Domain Services (Business Logic) ---

class UserService:
    def __init__(self, user_repo: UserRepository):
        self._user_repo = user_repo

    def create_user(self, user_id: str, name: Optional[str] = None) -> User:
        if not user_id or not isinstance(user_id, str):
            raise ValueError("Invalid user ID")

        existing = self._user_repo.get_user(user_id)
        if existing:
            raise ValueError(f"User with id '{user_id}' already exists")

        user = User(id=user_id, name=name or "")
        self._user_repo.save_user(user)
        return user


class OrderService:
    def __init__(self, user_repo: UserRepository, order_repo: OrderRepository):
        self._user_repo = user_repo
        self._order_repo = order_repo

    def place_order(self, user_id: str, amount: float) -> Order:
        if not user_id or not isinstance(user_id, str):
            raise ValueError("Invalid user ID")

        user = self._user_repo.get_user(user_id)
        if not user:
            raise ValueError(f"User with id '{user_id}' not found")

        order = Order(amount=amount)
        self._order_repo.add_order(user_id, order)
        return order


# --- Request Handler (Facade / Application Service) ---

class RequestHandler:
    def __init__(self, user_service: UserService, order_service: OrderService):
        self._user_service = user_service
        self._order_service = order_service

    def handle(self, req: dict) -> None:
        if not isinstance(req, dict):
            raise TypeError("Request must be a dictionary")

        req_type = req.get('t')
        if not req_type:
            raise ValueError("Request missing 't' field")

        if req_type == 'user':
            self._handle_user_request(req)
        elif req_type == 'order':
            self._handle_order_request(req)
        else:
            raise ValueError(f"Unknown request type: {req_type}")

    def _handle_user_request(self, req: dict) -> None:
        user_id = req.get('id')
        if not user_id or not isinstance(user_id, str):
            raise ValueError("User request missing valid 'id'")

        name = req.get('n')
        self._user_service.create_user(user_id, name)

    def _handle_order_request(self, req: dict) -> None:
        user_id = req.get('uid')
        if not user_id or not isinstance(user_id, str):
            raise ValueError("Order request missing valid 'uid'")

        amount = req.get('amt', 0.0)
        if not isinstance(amount, (int, float)):
            raise ValueError("Order amount must be a number")

        self._order_service.place_order(user_id, float(amount))


# --- Dependency Injection / Wiring ---

def create_request_handler(
    user_repo: UserRepository = None,
    order_repo: OrderRepository = None,
) -> RequestHandler:
    if user_repo is None:
        user_repo = InMemoryUserRepository()
    if order_repo is None:
        order_repo = InMemoryOrderRepository()

    user_service = UserService(user_repo)
    order_service = OrderService(user_repo, order_repo)

    return RequestHandler(user_service, order_service)
