```python
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Dict, Optional, List
import time

# ==========================================
# 1. DOMAIN MODELS (Pure business entities)
# ==========================================
@dataclass
class User:
    id: str
    name: str = ""
    created_at: float = 0.0
    orders: List[float] = field(default_factory=list)


# ==========================================
# 2. PERSISTENCE LAYER (Repository Pattern)
# ==========================================
class StorageBackend(ABC):
    """Abstraction for data persistence. Enables swapping implementations (DB, cache, etc.)."""

    @abstractmethod
    def get_user(self, user_id: str) -> Optional[User]: ...

    @abstractmethod
    def save_user(self, user: User) -> None: ...

    @abstractmethod
    def add_order_to_user(self, user_id: str, amount: float) -> None: ...


class InMemoryStorage(StorageBackend):
    """Concrete persistence implementation. Decoupled from business logic."""

    def __init__(self):
        self._users: Dict[str, User] = {}

    def get_user(self, user_id: str) -> Optional[User]:
        return self._users.get(user_id)

    def save_user(self, user: User) -> None:
        self._users[user.id] = user

    def add_order_to_user(self, user_id: str, amount: float) -> None:
        if not self._users.get(user_id):
            raise ValueError(f"Cannot add order: User '{user_id}' does not exist")
        self._users[user_id].orders.append(amount)


# ==========================================
# 3. SERVICE/HANDLER LAYER (Business Rules)
# ==========================================
class UserHandler:
    """Handles user creation logic. Depends on StorageBackend abstraction."""

    def __init__(self, storage: StorageBackend):
        self.storage = storage

    def handle(self, req: Dict[str, Any]) -> str:
        user_id = req.get("id")
        if not user_id:
            raise ValueError("Request missing required field 'id' for user creation")

        if self.storage.get_user(user_id):
            return "User already exists"

        user = User(
            id=user_id,
            name=req.get("n", ""),
            created_at=time.time()
        )
        self.storage.save_user(user)
        return "Saved user"


class OrderHandler:
    """Handles order placement logic. Depends on StorageBackend abstraction."""

    def __init__(self, storage: StorageBackend):
        self.storage = storage

    def handle(self, req: Dict[str, Any]) -> str:
        user_id = req.get("uid")
        if not user_id:
            raise ValueError("Request missing required field 'uid' for order")

        amount = req.get("amt", 0.0)
        self.storage.add_order_to_user(user_id, amount)
        return "Saved order"


# ==========================================
# 4. APPLICATION LAYER (Routing & DI Wiring)
# ==========================================
class RequestRouter:
    """Routes requests to appropriate handlers. Easy to extend with new request types."""

    def __init__(self, user_handler: UserHandler, order_handler: OrderHandler):
        self._handlers = {
            "user": user_handler,
            "order": order_handler
        }

    def handle(self, req: Dict[str, Any]) -> str:
        request_type = req.get("t")
        if not request_type:
            raise ValueError("Request missing required field 't' (type)")

        handler = self._handlers.get(request_type)
        if not handler:
            raise ValueError(f"Unsupported request type: '{request_type}'")

        return handler.handle(req)


class Application:
    """Root of dependency injection. Wires components together and provides safe execution."""

    def __init__(self):
        # Concrete dependencies are resolved here (Dependency Inversion Principle)
        storage = InMemoryStorage()
        self.router = RequestRouter(
            user_handler=UserHandler(storage),
            order_handler=OrderHandler(storage)
        )

    def execute(self, req: Dict[str, Any]) -> Dict[str, Any]:
        """Safe execution wrapper with structured error handling."""
        try:
            result = self.router.handle(req)
            return {"status": "success", "message": result}
        except ValueError as e:
            return {"status": "error", "code": 400, "message": str(e)}
        except Exception as e:
            # Catch-all for unexpected failures (logging should be added in production)
            return {"status": "error", "code": 500, "message": f"Internal error: {str(e)}"}


# ==========================================
# USAGE EXAMPLE
# ==========================================
if __name__ == "__main__":
    app = Application()

    # Valid user creation
    print(app.execute({"t": "user", "id": "u1", "n": "Alice"}))
    # {'status': 'success', 'message': 'Saved user'}

    # Valid order
    print(app.execute({"t": "order", "uid": "u1", "amt": 99.5}))
    # {'status': 'success', 'message': 'Saved order'}

    # Missing required field
    print(app.execute({"t": "order", "amt": 10.0}))
    # {'status': 'error', 'code': 400, 'message': "Request missing required field 'uid' for order"}

    # Unknown user
    print(app.execute({"t": "order", "uid": "u99"}))
    # {'status': 'error', 'code': 400, 'message': "Cannot add order: User 'u99' does not exist"}
```

### Key SOLID & Architecture Improvements:
| Principle | Implementation |
|-----------|----------------|
| **S**ingle Responsibility | `User` holds state, `StorageBackend` handles persistence, Handlers manage business rules, Router handles routing. |
| **O**pen/Closed | New request types only require adding a new Handler and registering it in `RequestRouter._handlers`. Core logic remains untouched. |
| **L**iskov Substitution | Any class implementing `StorageBackend` (e.g., PostgreSQL, Redis) can replace `InMemoryStorage` without breaking handlers. |
| **I**nterface Segregation | `StorageBackend` exposes only necessary methods. Handlers don't depend on unused persistence operations. |
| **D**ependency Inversion | High-level modules (`UserHandler`, `OrderHandler`) depend on the `StorageBackend` abstraction, not concrete implementations. Wiring happens at runtime via constructor injection. |

### Error Handling Strategy:
- **Fail-fast validation** in handlers raises descriptive `ValueError`s for missing/invalid fields.
- **Centralized try/catch** in `Application.execute()` converts exceptions into structured, API-friendly responses with HTTP-like status codes.
- **No silent failures** or global state mutations without explicit validation.

