        return self._data.get(user_id)

    def save(self, user: User) -> None:
        self._data[user.id] = user

# 4. Business Logic (Service)
class OrderService:
    """Handles the business logic for processing requests."""

    def __init__(self, user_repository: UserRepository):
        # Dependency Injection: The service depends on the abstraction, not the concrete implementation
        self.user_repo = user_repository

    def handle(self, request: Dict[str, Any]) -> None:
        """Routes the request to the appropriate handler."""
        try:
            req_type = request.get('t')

            if req_type == 'user':
                self._handle_user(request)
            elif req_type == 'order':
                self._handle_order(request)
            else:
                raise ValueError(f"Unknown request type: {req_type}")

        except KeyError as e:
            print(f"Missing required field: {e}")
        except Exception as e:
            print(f"Error processing request: {e}")

    def _handle_user(self, req: Dict[str, Any]) -> None:
        """Logic for creating a new user."""
        user_id = req.get('id')
        name = req.get('n', '')

        if not user_id:
            raise ValueError("User ID is required")

        existing_user = self.user_repo.get(user_id)
        if not existing_user:
            new_user = User(user_id, name)
            self.user_repo.save(new_user)
            print('Saved user')
        else:
            print('User already exists')

    def _handle_order(self, req: Dict[str, Any]) -> None:
        """Logic for adding an order to a user."""
        uid = req.get('uid')
        amt = req.get('amt', 0)

        if not uid:
            raise ValueError("User ID is required for order")

