    @abstractmethod
    def add_user(self, user: User) -> None:
        """Persist a new user."""
        ...

    @abstractmethod
    def get_user(self, user_id: str) -> Optional[User]:
        """Retrieve a user by id."""
        ...

    @abstractmethod
    def update_user(self, user: User) -> None:
        """Persist changes to an existing user."""
        ...

# In‑memory implementation of the repository
class InMemoryUserRepository(UserRepository):
    def __init__(self) -> None:
        self._storage: Dict[str, User] = {}

    def add_user(self, user: User) -> None:
        if user.id in self._storage:
            raise ValueError(f"User with id {user.id} already exists.")
        self._storage[user.id] = user

    def get_user(self, user_id: str) -> Optional[User]:
        return self._storage.get(user_id)

    def update_user(self, user: User) -> None:
        if user.id not in self._storage:
            raise KeyError(f"User with id {user.id} does not exist.")
        self._storage[user.id] = user

# ----------------------------------------------------------------------
# Service layer (business logic)
# ----------------------------------------------------------------------
class UserService:
    def __init__(self, repo: UserRepository) -> None:
        self._repo = repo

    def create_user(self, user_id: str, name: str) -> None:
        if not user_id:
            raise ValueError("User ID is required.")
        user = User(id=user_id, name=name)
        self._repo.add_user(user)
        logger.info("Saved user %s", user_id)

    def add_order(self, user_id: str, amount: float) -> None:
        if not user_id:
            raise ValueError("User ID is required.")
        if amount <= 0:
            raise ValueError("Order amount must be positive.")
        user = self._repo.get_user(user_id)
        if not user:
            raise KeyError(f"User with id {user_id} not found.")
        user.orders.append(amount)
        self._repo.update_user(user)
        logger.info("Saved order for user %s", user_id)

