```python
"""Domain models + services wired with dependency injection."""
from __future__ import annotations

import logging
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Dict, List, Optional

logger = logging.getLogger(__name__)


# --------------------------------------------------------------------------- #
# Domain layer (no persistence knowledge)
# --------------------------------------------------------------------------- #
class DomainError(Exception):
    """Base class for domain errors."""


class UserAlreadyExistsError(DomainError): ...
class UserNotFoundError(DomainError): ...


@dataclass(frozen=True)
class Order:
    """Immutable value object."""
    amount: float


@dataclass(frozen=True)
class User:
    """Aggregate root owning its orders."""
    id: str
    name: str = ""
    created_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    orders: List[Order] = field(default_factory=list)

    def add_order(self, amount: float) -> Order:
        order = Order(amount=amount)
        self.orders.append(order)
        return order


# --------------------------------------------------------------------------- #
# Persistence abstraction (Dependency Inversion Principle)
# --------------------------------------------------------------------------- #
class UserRepository(ABC):
    @abstractmethod
    def get(self, user_id: str) -> Optional[User]: ...

    @abstractmethod
    def save(self, user: User) -> None: ...


class InMemoryUserRepository(UserRepository):
    """Concrete store — swap for a DB/Redis/file impl without touching callers."""

    def __init__(self) -> None:
        self._store: Dict[str, User] = {}

    def get(self, user_id: str) -> Optional[User]:
        return self._store.get(user_id)

    def save(self, user: User) -> None:
        self._store[user.id] = user


# --------------------------------------------------------------------------- #
# Application service (Single Responsibility)
# --------------------------------------------------------------------------- #
class UserService:
    def __init__(self, repository: UserRepository) -> None:
        self._repository = repository  # injected abstraction

    def create_user(self, user_id: str, name: str) -> User:
        if self._repository.get(user_id) is not None:
            raise UserAlreadyExistsError(f"User '{user_id}' already exists")

        user = User(id=user_id, name=name)
        self._repository.save(user)
        logger.info("Saved user %s", user_id)
        return user

    def add_order(self, user_id: str, amount: float) -> Order:
        user = self._repository.get(user_id)
        if user is None:
            raise UserNotFoundError(f"User '{user_id}' not found")

        order = user.add_order(amount)
        self._repository.save(user)
        logger.info("Saved order %s for user %s", amount, user_id)
        return order


# --------------------------------------------------------------------------- #
# Message dispatch (Open/Closed — add new message kinds without editing this)
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Message:
    kind: str
    payload: dict


class MessageHandler(ABC):
    @abstractmethod
    def handles(self, message: Message) -> bool: ...

    @abstractmethod
    def handle(self, message: Message) -> None: ...


class CreateUserHandler(MessageHandler):
    def __init__(self, service: UserService) -> None:
        self._service = service

    def handles(self, message: Message) -> bool:
        return message.kind == "user"

    def handle(self, message: Message) -> None:
        payload = message.payload
        if "id" not in payload:
            raise ValueError("User request requires an 'id'")
        self._service.create_user(payload["id"], payload.get("n", ""))


class AddOrderHandler(MessageHandler):
    def __init__(self, service: UserService) -> None:
        self._service = service

    def handles(self, message: Message) -> bool:
        return message.kind == "order"

    def handle(self, message: Message) -> None:
        payload = message.payload
        if "uid" not in payload:
            raise ValueError("Order request requires a 'uid'")
        self._service.add_order(payload["uid"], payload.get("amt", 0))


class MessageRouter:
    def __init__(self, handlers: List[MessageHandler]) -> None:
        self._handlers = handlers

    def dispatch(self, message: Message) -> None:
        for handler in self._handlers:
            if handler.handles(message):
                handler.handle(message)
                return
        raise ValueError(f"No handler registered for message kind '{message.kind}'")


def build_application() -> MessageRouter:
    """Composition root — wires the object graph once at startup."""
    repository = InMemoryUserRepository()
    service = UserService(repository)
    return MessageRouter([CreateUserHandler(service), AddOrderHandler(service)])


# --------------------------------------------------------------------------- #
# Usage
# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    router = build_application()

    router.dispatch(Message("user", {"id": "u1", "n": "Alice"}))
    router.dispatch(Message("order", {"uid": "u1", "amt": 42}))

    try:
        router.dispatch(Message("order", {"uid": "ghost", "amt": 10}))
    except UserNotFoundError as exc:
        logger.warning("Handled gracefully: %s", exc)
```

## What changed and why

| Concern | Before | After |
|---|---|---|
| **Global mutable state** | module-level `DATA = {}` | injected `UserRepository`, no globals |
| **Persistence vs domain** | dicts with mixed keys | `User`/`Order` models + separate repository abstraction |
| **Error handling** | silent `if u:` swallowing missing users | explicit `UserNotFoundError` / `UserAlreadyExistsError` + input validation |
| **Extensibility** | new type = edit `handle` with more `elif` | new message kind = add a `MessageHandler` subclass (OCP) |
| **Testability** | hard to isolate | swap `InMemoryUserRepository` for a fake/DB impl |

**SOLID mapping:**
- **SRP** — models, repository, service, and each handler own one responsibility.
- **OCP** — `MessageRouter` is closed for modification; new message types are added by registering a handler.
- **LSP** — any `UserRepository` impl can replace `InMemoryUserRepository`.
- **ISP** — the repository exposes only `get`/`save`, not a monolithic interface.
- **DIP** — `UserService` depends on the `UserRepository` abstraction, injected via constructor.

