from __future__ import annotations

import time
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Dict, Mapping, Optional, Protocol, runtime_checkable

class ApplicationError(Exception):
    def __init__(self, message: str, status: int = 400) -> None:
        super().__init__(message)
        self.status = status

class InvalidRequestError(ApplicationError):
    pass

class UserNotFoundError(ApplicationError):
    def __init__(self, message: str = "User not found") -> None:
        super().__init__(message, status=404)

class PersistenceError(ApplicationError):
    def __init__(self, message: str = "Persistence error") -> None:
        super().__init__(message, status=500)

@runtime_checkable
class Clock(Protocol):
    def now(self) -> float: ...

class SystemClock:
    def now(self) -> float:
        return time.time()

@dataclass
class Order:
    amount: float
    created: float = field(default_factory=time.time)

@dataclass
class User:
    user_id: str
    name: str
    created: float
    orders: list[Order] = field(default_factory=list)

class UserRepository(ABC):
    @abstractmethod
    def get(self, user_id: str) -> Optional[User]: ...
    @abstractmethod
    def save(self, user: User) -> None: ...
    @abstractmethod
    def exists(self, user_id: str) -> bool: ...

class InMemoryUserRepository(UserRepository):
    def __init__(self) -> None:
        self._users: Dict[str, User] = {}

    def get(self, user_id: str) -> Optional[User]:
        return self._users.get(user_id)

    def save(self, user: User) -> None:
        self._users[user.user_id] = user

    def exists(self, user_id: str) -> bool:
        return user_id in self._users

class UserService:
    def __init__(self, users: UserRepository, clock: Clock = SystemClock()) -> None:
        self._users = users
        self._clock = clock

    def create_if_absent(self, user_id: str, name: str) -> tuple[User, bool]:
        if not user_id:
            raise InvalidRequestError("User id is required")
        existing = self._users.get(user_id)
        if existing is not None:
            return existing, False
        user = User(user_id=user_id, name=name, created=self._clock.now())
        self._users.save(user)
        return user, True

class OrderService:
    def __init__(self, users: UserRepository, clock: Clock = SystemClock()) -> None:
        self._users = users
        self._clock = clock

    def add_for_user(self, user_id: str, amount: float) -> Order:
        if not user_id:
            raise InvalidRequestError("User id is required")
        user = self._users.get(user_id)
        if user is None:
            raise UserNotFoundError()
        order = Order(amount=amount, created=self._clock.now())
        user.orders.append(order)
        self._users.save(user)
        return order

class RequestHandler(ABC):
    @abstractmethod
    def handle(self, payload: Mapping[str, Any]) -> Dict[str, Any]: ...

class UserRequestHandler(RequestHandler):
    def __init__(self, service: UserService) -> None:
        self._service = service

    def handle(self, payload: Mapping[str, Any]) -> Dict[str, Any]:
        user_id = payload.get("id")
        if user_id is None:
            raise InvalidRequestError("id is required")
        name = payload.get("n", "")
        if not isinstance(name, str):
            name = str(name)
        user, created = self._service.create_if_absent(str(user_id), name)
        return {
            "status": "ok",
            "message": "Saved user" if created else "User already exists",
            "user_id": user.user_id,
        }

class OrderRequestHandler(RequestHandler):
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle(self, payload: Mapping[str, Any]) -> Dict[str, Any]:
        user_id = payload.get("uid")
        if user_id is None:
            raise InvalidRequestError("uid is required")
        amount = payload.get("amt", 0)
        try:
            amount = float(amount)
        except (TypeError, ValueError) as exc:
            raise InvalidRequestError("amt must be numeric") from exc
        order = self._service.add_for_user(str(user_id), amount)
        return {
            "status": "ok",
            "message": "Saved order",
            "user_id": user_id,
            "amount": order.amount,
        }

class RequestProcessor:
    def __init__(self, handlers: Optional[Mapping[str, RequestHandler]] = None) -> None:
        self._handlers: Dict[str, RequestHandler] = dict(handlers or {})

    def register(self, request_type: str, handler: RequestHandler) -> None:
        self._handlers[request_type] = handler

    def handle(self, request: Mapping[str, Any]) -> Dict[str, Any]:
        if not isinstance(request, Mapping):
            raise InvalidRequestError("Request must be a mapping")
        request_type = request.get("t")
        if request_type is None:
            raise InvalidRequestError("t is required")
        handler = self._handlers.get(str(request_type))
        if handler is None:
            raise InvalidRequestError(f"Unsupported request type: {request_type}")
        try:
            return handler.handle(request)
        except ApplicationError as exc:
            return {"status": "error", "message": str(exc), "code": exc.status}
        except Exception:
            return {"status": "error", "message": "Internal error", "code": 500}

def build_processor() -> RequestProcessor:
    users = InMemoryUserRepository()
    clock = SystemClock()
    user_service = UserService(users, clock)
    order_service = OrderService(users, clock)
    processor = RequestProcessor()
    processor.register("user", UserRequestHandler(user_service))
    processor.register("order", OrderRequestHandler(order_service))
    return processor
