        ...


class RequestHandler(ABC):
    """Abstraction for handling a specific request type."""

    @abstractmethod
    def handle(self, req: Dict[str, Any]) -> None:
        """Process a request of this handler's type."""
        ...


# =============================================================================
# Concrete Implementations
# =============================================================================

class SystemClock(Clock):
    """Uses the system clock."""

    def now(self) -> float:
        return time.time()


class PrintLogger(Logger):
    """Logs to stdout."""

    def info(self, message: str) -> None:
        print(message)


class InMemoryUserRepository(UserRepository):
    """In-memory user storage."""

    def __init__(self) -> None:
        self._users: Dict[str, User] = {}

    def get(self, user_id: str) -> Optional[User]:
        return self._users.get(user_id)

    def save(self, user: User) -> None:
        self._users[user.id] = user

    def exists(self, user_id: str) -> bool:
        return user_id in self._users


class InMemoryOrderRepository(OrderRepository):
    """In-memory order storage (orders are stored within users)."""

    def __init__(self, user_repository: UserRepository) -> None:
        self._user_repo = user_repository

    def add_to_user(self, user_id: str, amount: float) -> bool:
        user = self._user_repo.get(user_id)
        if user is not None:
            user.orders.append(amount)
            return True
        return False


# =============================================================================
# Services (Business Logic)
# =============================================================================

class UserService:
    """Handles user-related business logic."""

    def __init__(self, user_repo: UserRepository, clock: Clock, logger: Logger) -> None:
        self._user_repo = user_repo
        self._clock = clock
        self._logger = logger

    def create_user(self, user_id: str, name: str) -> User:
        """Create a new user. Raises ValueError if the user already exists."""
        if self._user_repo.exists(user_id):
            raise ValueError(f"User '{user_id}' already exists")

        user = User(id=user_id, name=name, created_at=self._clock.now())
        self._user_repo.save(user)
        self._logger.info("Saved user")
        return user


class OrderService:
    """Handles order-related business logic."""

    def __init__(self, order_repo: OrderRepository, logger: Logger) -> None:
        self._order_repo = order_repo
        self._logger = logger

    def add_order(self, user_id: str, amount: float) -> bool:
        """Add an order for a user. Returns True if the order was saved."""
        saved = self._order_repo.add_to_user(user_id, amount)
        if saved:
            self._logger.info("Saved order")
        return saved


# =============================================================================
# Request Handlers (Strategy Pattern)
# =============================================================================

class CreateUserHandler(RequestHandler):
    """Handles 'user' type requests."""

    def __init__(self, user_service: UserService) -> None:
        self._user_service = user_service

    def handle(self, req: Dict[str, Any]) -> None:
        user_id = req.get("id")
        if not user_id:
            raise ValueError("Missing required field 'id' for user request")

        name = req.get("n", "")
        self._user_service.create_user(user_id, name)


class AddOrderHandler(RequestHandler):
    """Handles 'order' type requests."""

    def __init__(self, order_service: OrderService) -> None:
        self._order_service = order_service

    def handle(self, req: Dict[str, Any]) -> None:
        user_id = req.get("uid")
        if not user_id:
            raise ValueError("Missing required field 'uid' for order request")

        amount = req.get("amt", 0)
        if not isinstance(amount, (int, float)):
            raise ValueError(f"Invalid amount: {amount!r} (must be numeric)")

        self._order_service.add_order(user_id, float(amount))


# =============================================================================
# Request Dispatcher (Facade)
# =============================================================================

class RequestDispatcher:
    """Routes requests to the appropriate handler."""

    def __init__(self) -> None:
        self._handlers: Dict[str, RequestHandler] = {}

    def register(self, request_type: str, handler: RequestHandler) -> None:
        """Register a handler for a specific request type."""
        self._handlers[request_type] = handler

    def dispatch(self, req: Dict[str, Any]) -> None:
        """Route and process a request."""
        request_type = req.get("t")
        if not request_type:
            raise ValueError("Missing required field 't' (request type)")

        handler = self._handlers.get(request_type)
        if handler is None:
            raise ValueError(f"Unknown request type: '{request_type}'")

        handler.handle(req)


# =============================================================================
# Composition Root (Dependency Injection Container / Factory)
# =============================================================================

def create_dispatcher() -> RequestDispatcher:
    """Wire up all dependencies and return a configured dispatcher."""
    clock = SystemClock()
    logger = PrintLogger()

    user_repo = InMemoryUserRepository()
    order_repo = InMemoryOrderRepository(user_repo)

    user_service = UserService(user_repo, clock, logger)
    order_service = OrderService(order_repo, logger)

    dispatcher = RequestDispatcher()
    dispatcher.register("user", CreateUserHandler(user_service))
    dispatcher.register("order", AddOrderHandler(order_service))

    return dispatcher


# =============================================================================
# Public API (replaces the original handle function)
# =============================================================================

_dispatcher = create_dispatcher()


