```python
"""
Refactored request processing system following SOLID principles.

Architecture:
- Domain Layer:     User entity with business rules
- Infrastructure:   UserRepository abstraction + in-memory implementation (persistence)
- Application:      Handlers, Router, Processor with dependency injection

SOLID compliance:
- SRP: Each class has one responsibility (entity, persistence, handling, routing, orchestration)
- OCP: New request types / storage backends can be added without modifying existing code
- LSP: Any UserRepository or RequestHandler implementation is substitutable
- ISP: Focused interfaces (no fat classes)
- DIP: High-level modules depend on abstractions; dependencies injected via constructors
"""

from abc import ABC, abstractmethod
from typing import Dict, List, Optional
import time


# =============================================================================
# Domain Layer
# =============================================================================

class User:
    """Domain entity representing a user."""

    def __init__(self, user_id: str, name: str = "", created_at: Optional[float] = None) -> None:
        self.id = user_id
        self.name = name
        self.created_at = created_at if created_at is not None else time.time()
        self.orders: List[float] = []

    def add_order(self, amount: float) -> None:
        """Add an order amount to this user's order history."""
        self.orders.append(amount)


# =============================================================================
# Infrastructure Layer — Persistence Abstraction (DIP)
# =============================================================================

class UserRepository(ABC):
    """Abstraction for user persistence. Swap implementations (DB, file, cache) freely."""

    @abstractmethod
    def get(self, user_id: str) -> Optional[User]:
        """Retrieve a user by ID. Returns None if not found."""
        raise NotImplementedError

    @abstractmethod
    def save(self, user: User) -> None:
        """Persist a user (create or update)."""
        raise NotImplementedError

    @abstractmethod
    def exists(self, user_id: str) -> bool:
        """Check whether a user with the given ID exists."""
        raise NotImplementedError


class InMemoryUserRepository(UserRepository):
    """In-memory implementation for demonstration and testing."""

    def __init__(self) -> None:
        self._store: Dict[str, User] = {}

    def get(self, user_id: str) -> Optional[User]:
        return self._store.get(user_id)

    def save(self, user: User) -> None:
        self._store[user.id] = user

    def exists(self, user_id: str) -> bool:
        return user_id in self._store


# =============================================================================
# Application Layer — Domain Exceptions (Proper Error Handling)
# =============================================================================

class RequestError(Exception):
    """Base exception for request processing errors."""


class ValidationError(RequestError):
    """Raised when a request is malformed or missing required fields."""


class NotFoundError(RequestError):
    """Raised when a referenced entity does not exist."""


class DuplicateError(RequestError):
    """Raised when attempting to create a duplicate entity."""


# =============================================================================
# Application Layer — Handlers (SRP: one responsibility per handler)
# =============================================================================

class RequestHandler(ABC):
    """Interface for request handlers. Supports OCP — add new types without modifying existing code."""

    @abstractmethod
    def can_handle(self, request: dict) -> bool:
        """Return True if this handler is responsible for the given request."""
        raise NotImplementedError

    @abstractmethod
    def handle(self, request: dict) -> str:
        """Process the request and return a success message. Raises RequestError on failure."""
        raise NotImplementedError


class UserHandler(RequestHandler):
    """Handles user creation requests."""

    def __init__(self, repository: UserRepository) -> None:
        self._repository = repository

    def can_handle(self, request: dict) -> bool:
        return request.get("t") == "user"

    def handle(self, request: dict) -> str:
        user_id = request.get("id")
        if not user_id:
            raise ValidationError("User request is missing required 'id' field")

        if self._repository.exists(user_id):
            raise DuplicateError(f"User '{user_id}' already exists")

        user = User(user_id=user_id, name=request.get("n", ""))
        self._repository.save(user)
        return "Saved user"


class OrderHandler(RequestHandler):
    """Handles order creation requests."""

    def __init__(self, repository: UserRepository) -> None:
        self._repository = repository

    def can_handle(self, request: dict) -> bool:
        return request.get("t") == "order"

    def handle(self, request: dict) -> str:
        user_id = request.get("uid")
        if not user_id:
            raise ValidationError("Order request is missing required 'uid' field")

        user = self._repository.get(user_id)
        if user is None:
            raise NotFoundError(f"User '{user_id}' not found")

        amount = request.get("amt", 0)
        if not isinstance(amount, (int, float)):
            raise ValidationError(f"Order amount must be numeric, got {type(amount).__name__}")

        user.add_order(float(amount))
        self._repository.save(user)  # Explicitly persist the modification
        return "Saved order"


# =============================================================================
# Application Layer — Router (OCP: extensible without modification)
# =============================================================================

class RequestRouter:
    """Routes incoming requests to the appropriate handler."""

    def __init__(self, handlers: List[RequestHandler]) -> None:
        self._handlers = handlers

    def route(self, request: dict) -> str:
        for handler in self._handlers:
            if handler.can_handle(request):
                return handler.handle(request)
        raise ValidationError(f"Unknown request type: {request.get('t', '<missing>')}")


# =============================================================================
# Application Layer — Processor (Orchestration + Error Handling)
# =============================================================================

class RequestProcessor:
    """Top-level entry point. Orchestrates routing and translates errors into results."""

    def __init__(self, router: RequestRouter) -> None:
        self._router = router

    def process(self, request: dict) -> str:
        try:
            return self._router.route(request)
        except RequestError as exc:
            return f"ERROR: {exc}"


# =============================================================================
# Composition Root — Dependency Injection Wiring
# =============================================================================

def create_processor() -> RequestProcessor:
    """Wire up all dependencies. This is the single place where concrete classes are chosen."""
    repository = InMemoryUserRepository()

    handlers: List[RequestHandler] = [
        UserHandler(repository),
        OrderHandler(repository),
    ]

    router = RequestRouter(handlers)
    return RequestProcessor(router)


# =============================================================================
# Usage Example
# =============================================================================

if __name__ == "__main__":
    processor = create_processor()

    test_requests = [
        {"t": "user",  "id": "u1", "n": "Alice"},
        {"t": "order", "uid": "u1", "amt": 99.5},
        {"t": "user",  "id": "u1"},                        # Duplicate user
        {"t": "order", "uid": "u9"},                        # Non-existent user
        {"t": "unknown"},                                   # Unknown type
        {"t": "user"},                                      # Missing id
        {"t": "order", "uid": "u1", "amt": "bad"},         # Invalid amount
    ]

    for req in test_requests:
        print(f"Request: {req}")
        print(f"Result:  {processor.process(req)}")
        print()
```

**Key improvements over the original:**

| Issue in Original | Refactored Solution |
|---|---|
| Global mutable `DATA` dict | Encapsulated in `InMemoryUserRepository`, injected via DI |
| One function doing everything (SRP violation) | Separated into `User`, `Repository`, `Handlers`, `Router`, `Processor` |
| No abstraction for persistence (DIP violation) | `UserRepository` ABC — swap in a DB-backed implementation without touching handlers |
| Silent failures / no error handling | Custom exceptions (`ValidationError`, `NotFoundError`, `DuplicateError`) caught by processor |
| Hard to extend with new request types (OCP violation) | Add a new `RequestHandler` subclass and register it — no existing code changes |
| Implicit in-place mutation of global state | Explicit `repository.save(user)` after modifications |
| No type safety | Full type hints throughout |

To use a different storage backend (e.g., SQLite), simply implement `UserRepository` and pass it to the handlers in `create_processor()` — no other code changes needed.

