"""
Refactured request processing system following SOLID principles.

Layers:
- Domain: User entity with business rules
- Infrastructure: UserRepository abstraction and in-memory implementation
- Application: Handlers, Router, Processor with dependency injection
"""

from abc import ABC, abstractmethod
from typing import Dict, List, Optional, Protocol
import time


# =============================================================================
# Domain Layer
# =============================================================================

class User:
    """Domain entity representing a user."""

    def __init__(self, user_id: str, name: str = "", created_at: Optional[float] = None):
        self.id = user_id
        self.name = name
        self.created_at = created_at if created_at is not None else time.time()
        self.orders: List[float] = []

    def add_order(self, amount: float) -> None:
