"""
Refactored procedural code into clean, SOLID, object-oriented Python
with dependency injection, separation of concerns, and proper error handling.
"""

from __future__ import annotations

import time
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional


# ─── Domain Models ────────────────────────────────────────────────────────────

@dataclass
class User:
    """Represents a user in the domain."""
    id: str
    name: str = ""
    created_at: float = field(default_factory=time.time)
    orders: List[float] = field(default_factory=list)

    def add_order(self, amount: float) -> None:
        """Add an order amount to this user's order history."""
        self.orders.append(amount)


@dataclass
class Order:
    """Represents an order event."""
    user_id: str
    amount: float


# ─── Errors ───────────────────────────────────────────────────────────────────

class DomainError(Exception):
    """Base exception for domain-level errors."""


class UserNotFoundError(DomainError):
    """Raised when a user ID is not found."""

    def __init__(self, user_id: str) -> None:
        super().__init__(f"User '{user_id}' not found.")
        self.user_id = user_id


class InvalidRequestError(DomainError):
    """Raised when a request is malformed."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


# ─── Persistence (Repository Pattern) ─────────────────────────────────────────

class UserRepository(ABC):
    """Abstract interface for user persistence.

    This is the dependency that gets injected, allowing us to swap
    implementations (in-memory, database, etc.) without touching domain logic.
    """

    @abstractmethod
    def save_user(self, user: User) -> None:
        """Persist a user."""

    @abstractmethod
    def get_user(self, user_id: str) -> Optional[User]:
        """Retrieve a user by ID, or None if not found."""

    @abstractmethod
    def save_order(self, user_id: str, amount: float) -> None:
        """Persist an order for a given user."""


class InMemoryUserRepository(UserRepository):
    """In-memory implementation of UserRepository (for testing / dev)."""

    def __init__(self) -> None:
        self._users: Dict[str, User] = {}

    def save_user(self, user: User) -> None:
        self._users[user.id] = user

    def get_user(self, user_id: str) -> Optional[User]:
        return self._users.get(user_id)

    def save_order(self, user_id: str, amount: float) -> None:
        user = self._users.get(user_id)
        if user is None:
            raise UserNotFoundError(user_id)
        user.add_order(amount)


# ─── Services (Business Logic) ────────────────────────────────────────────────

class UserService:
    """Handles user-related business logic.

    Depends on the abstract UserRepository via constructor injection.
    """

    def __init__(self, repository: UserRepository) -> None:
        self._repo = repository

    def create_user(self, user_id: str, name: str = "") -> User:
        """Create and persist a new user.

        Raises:
            InvalidRequestError: If user_id is missing or empty.
        """
        if not user_id:
            raise InvalidRequestError("User ID must be provided and non-empty.")

        user = User(id=user_id, name=name)
        self._repo.save_user(user)
        return user

    def get_user(self, user_id: str) -> User:
        """Retrieve a user by ID.

        Raises:
            UserNotFoundError: If the user does not exist.
        """
        user = self._repo.get_user(user_id)
        if user is None:
            raise UserNotFoundError(user_id)
        return user


class OrderService:
    """Handles order-related business logic.

    Depends on the abstract UserRepository via constructor injection.
    """

    def __init__(self, repository: UserRepository) -> None:
        self._repo = repository

    def place_order(self, user_id: str, amount: float) -> None:
        """Record an order for a user.

        Raises:
            InvalidRequestError: If user_id is missing or amount is invalid.
            UserNotFoundError: If the user does not exist.
        """
        if not user_id:
            raise InvalidRequestError("User ID must be provided and non-empty.")
        if not isinstance(amount, (int, float)) or amount < 0:
            raise InvalidRequestError(
                f"Invalid amount: {amount!r}. Must be a non-negative number."
            )

        self._repo.save_order(user_id, amount)


# ─── Request Handler (Facade / Adapter) ──────────────────────────────────────

class RequestHandler:
    """Adapts raw request dictionaries to domain operations.

    This is the entry point that replaces the original `handle()` function.
    It orchestrates the services and translates between the external
    request format and the internal domain model.
    """

    def __init__(
        self,
        user_service: UserService,
        order_service: OrderService,
        logger: Optional[Any] = None,
    ) -> None:
        self._user_service = user_service
        self._order_service = order_service
        self._logger = logger or _DefaultLogger()

    def handle(self, req: Dict[str, Any]) -> Dict[str, Any]:
        """Process a request dictionary and return a response.

        Args:
            req: A dictionary with at least a 't' (type) key.

        Returns:
            A response dictionary with 'status' and optional 'message'.

        Raises:
            InvalidRequestError: If the request is malformed.
            UserNotFoundError: If a referenced user does not exist.
        """
        req_type = req.get('t')
        if req_type is None:
            raise InvalidRequestError("Request must contain a 't' (type) field.")

        if req_type == 'user':
            return self._handle_user(req)
        elif req_type == 'order':
            return self._handle_order(req)
        else:
            raise InvalidRequestError(f"Unknown request type: {req_type!r}")

    def _handle_user(self, req: Dict[str, Any]) -> Dict[str, Any]:
        user_id = req.get('id')
        if not user_id:
            raise InvalidRequestError("'id' field is required for user requests.")

        name = req.get('n', '')
        self._user_service.create_user(user_id, name)
        self._logger.info(f"Saved user: {user_id}")
        return {'status': 'ok', 'message': 'User saved.'}

    def _handle_order(self, req: Dict[str, Any]) -> Dict[str, Any]:
        user_id = req.get('uid')
        if not user_id:
            raise InvalidRequestError("'uid' field is required for order requests.")

        amount = req.get('amt', 0)
        self._order_service.place_order(user_id, amount)
        self._logger.info(f"Saved order: user={user_id}, amount={amount}")
        return {'status': 'ok', 'message': 'Order saved.'}


# ─── Logging (Dependency Injection) ───────────────────────────────────────────

class _DefaultLogger:
    """Simple logger that prints to stdout (replaces `print`)."""

    def info(self, message: str) -> None:
        print(message)


class NullLogger:
    """No-op logger for tests or silent operation."""

    def info(self, message: str) -> None:
        pass


# ─── Factory / Composition Root ───────────────────────────────────────────────

def build_request_handler(
    repository: Optional[UserRepository] = None,
    logger: Optional[Any] = None,
) -> RequestHandler:
    """Composition root: wires up dependencies and returns a ready-to-use handler.

    This centralizes object construction, making it easy to swap
    implementations (e.g., for testing with a fake repository).
    """
    if repository is None:
        repository = InMemoryUserRepository()

    user_service = UserService(repository)
    order_service = OrderService(repository)

    return RequestHandler(
        user_service=user_service,
        order_service=order_service,
        logger=logger,
    )


# ─── Convenience: drop-in replacement for the original `handle` ──────────────

def handle(req: Dict[str, Any]) -> Dict[str, Any]:
    """Drop-in replacement for the original procedural `handle` function.

    Uses a module-level handler built with the default in-memory repository.
    For production, prefer `build_request_handler()` with explicit dependencies.
