import time
from abc import ABC, abstractmethod
from typing import Any, Dict, Optional


class PersistenceError(Exception):
    """Raised when a persistence operation fails."""
    pass


class DomainError(Exception):
    """Raised when a domain rule is violated."""
    pass


class UserNotFoundError(DomainError):
    """Raised when a user is not found."""
    pass


class InvalidRequestError(DomainError):
    """Raised when a request is malformed or invalid."""
    pass


class User:
    """Domain model for a User."""

    def __init__(self, user_id: str, name: str = "", created: Optional[float] = None):
        self.id = user_id
        self.name = name
        self.created = created if created is not None else time.time()
        self.orders: list = []

    def add_order(self, amount: float) -> None:
        """Add an order to the user."""
        self.orders.append(amount)


class Order:
    """Domain model for an Order."""

    def __init__(self, amount: float):
        self.amount = amount


class UserRepository(ABC):
    """Abstract base class for user persistence."""

    @abstractmethod
    def save(self, user: User) -> None:
        """Save a user to the repository."""
        pass

    @abstractmethod
    def find_by_id(self, user_id: str) -> Optional[User]:
        """Find a user by ID."""
        pass

    @abstractmethod
    def exists(self, user_id: str) -> bool:
        """Check if a user exists."""
        pass


class InMemoryUserRepository(UserRepository):
    """In-memory implementation of UserRepository."""

    def __init__(self):
        self._store: Dict[str, User] = {}

    def save(self, user: User) -> None:
        """Save a user to the in-memory store."""
        try:
            self._store[user.id] = user
        except Exception as e:
            raise PersistenceError(f"Failed to save user {user.id}: {e}") from e

    def find_by_id(self, user_id: str) -> Optional[User]:
        """Find a user by ID."""
        return self._store.get(user_id)

    def exists(self, user_id: str) -> bool:
        """Check if a user exists."""
        return user_id in self._store


class OrderRepository(ABC):
    """Abstract base class for order persistence."""

    @abstractmethod
    def save(self, user_id: str, order: Order) -> None:
        """Save an order associated with a user."""
        pass


class InMemoryOrderRepository(OrderRepository):
    """In-memory implementation of OrderRepository."""

    def __init__(self, user_repository: UserRepository):
        self._user_repo = user_repository

    def save(self, user_id: str, order: Order) -> None:
        """Save an order by adding it to the user's orders list."""
        user = self._user_repo.find_by_id(user_id)
        if user is None:
            raise UserNotFoundError(f"User {user_id} not found")
        user.add_order(order.amount)


class RequestHandler:
    """Handles incoming requests and coordinates domain logic."""

    def __init__(
        self,
        user_repository: UserRepository,
        order_repository: OrderRepository,
        logger: Optional[Any] = None,
    ):
        self._user_repo = user_repository
        self._order_repo = order_repository
        self._logger = logger

    def _log(self, message: str) -> None:
        """Log a message if a logger is provided."""
        if self._logger is not None:
            self._logger.info(message)
        else:
            print(message)

    def handle(self, req: Dict[str, Any]) -> None:
        """
        Handle an incoming request.

        Args:
            req: A dictionary containing request data with at least a 't' key.

        Raises:
            InvalidRequestError: If the request is malformed.
            UserNotFoundError: If a referenced user is not found.
            PersistenceError: If a persistence operation fails.
        """
        if not isinstance(req, dict):
            raise InvalidRequestError("Request must be a dictionary")

        req_type = req.get('t')
        if req_type is None:
            raise InvalidRequestError("Request must contain a 't' field")

        if req_type == 'user':
            self._handle_user_request(req)
        elif req_type == 'order':
            self._handle_order_request(req)
        else:
            raise InvalidRequestError(f"Unknown request type: {req_type}")

    def _handle_user_request(self, req: Dict[str, Any]) -> None:
        """Handle a user creation request."""
        user_id = req.get('id')
        if user_id is None:
            raise InvalidRequestError("User request must contain an 'id' field")

        if self._user_repo.exists(user_id):
            self._log(f"User {user_id} already exists, skipping creation")
            return

        name = req.get('n', '')
        user = User(user_id=user_id, name=name)
        self._user_repo.save(user)
        self._log('Saved user')

    def _handle_order_request(self, req: Dict[str, Any]) -> None:
        """Handle an order creation request."""
        user_id = req.get('uid')
        if user_id is None:
            raise InvalidRequestError("Order request must contain a 'uid' field")

        amount = req.get('amt', 0)
        if not isinstance(amount, (int, float)):
            raise InvalidRequestError("Order amount must be a number")

        order = Order(amount=amount)
        self._order_repo.save(user_id, order)
        self._log('Saved order')


def create_default_handler() -> RequestHandler:
    """
    Factory function to create a RequestHandler with default in-memory repositories.

    Returns:
        A configured RequestHandler instance.
    """
    user_repo = InMemoryUserRepository()
    order_repo = InMemoryOrderRepository(user_repo)
    return RequestHandler(user_repository=user_repo, order_repository=order_repo)
