from __future__ import annotations
import logging
import time
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation
from typing import Any, Mapping, Optional

# Domain exceptions
class DomainError(Exception): ...
class DuplicateUserError(DomainError): ...
class UserNotFoundError(DomainError): ...
class InvalidRequestError(DomainError): ...
class UnknownRequestTypeError(InvalidRequestError): ...
class MissingUserIdError(InvalidRequestError): ...
class InvalidAmountError(InvalidRequestError): ...

# Domain models
@dataclass(frozen=True)
class UserId:
    value: str
    def __post_init__(self):
        if not self.value:
            raise ValueError("User id must not be empty")

@dataclass(frozen=True)
class Order:
    amount: Decimal
    created_at: float

class User:
    def __init__(self, user_id: UserId, name: str, created_at: float, orders: list[Order] | None = None):
        self._id = user_id
        self._name = name
        self._created_at = created_at
        self._orders = list(orders or [])
    @property id, name, created_at, orders
    def add_order(self, amount: Decimal, created_at: float) -> Order:
        order = Order(amount, created_at)
        self._orders.append(order)
        return order

# Persistence records
@dataclass
class UserRecord:
    id: str
    name: str
    created_at: float
    orders: list[Decimal] = field(default_factory=list)

# Mapping
def user_to_record(user: User) -> UserRecord:
    return UserRecord(user.id.value, user.name, user.created_at, [o.amount for o in user.orders])
def record_to_user(record: UserRecord) -> User:
    return User(UserId(record.id), record.name, record.created_at, [Order(amount, record.created_at) for amount in record.orders])

# Persistence abstraction
class UserRepository(ABC):
    @abstractmethod
    def exists(self, user_id: str) -> bool: ...
    @abstractmethod
    def get(self, user_id: str) -> Optional[UserRecord]: ...
    @abstractmethod
    def save(self, record: UserRecord) -> None: ...

class InMemoryUserRepository(UserRepository):
    def __init__(self):
        self._data: dict[str, UserRecord] = {}
    def exists... return user_id in self._data
    def get... return self._data.get(user_id)
    def save... self._data[record.id] = record

# Clock
class Clock(ABC):
    @abstractmethod
    def now(self) -> float: ...
class SystemClock(Clock):
    def now(self): return time.time()

# Application services
class UserCreationService:
    def __init__(self, repository: UserRepository, clock: Clock):
        self._repository = repository
        self._clock = clock
    def create(self, user_id: str, name: str) -> User:
        if not user_id:
            raise MissingUserIdError("User id is required")
        if self._repository.exists(user_id):
            raise DuplicateUserError(f"User {user_id} already exists")
        user = User(UserId(user_id), name, self._clock.now())
        self._repository.save(user_to_record(user))
        return user

class OrderService:
    def __init__(self, repository: UserRepository, clock: Clock):
        ...
    def add_order(self, user_id: str, amount: Decimal) -> Order:
        if not user_id:
            raise MissingUserIdError("User id is required")
        record = self._repository.get(user_id)
        if record is None:
            raise UserNotFoundError(f"User {user_id} not found")
        user = record_to_user(record)
        order = user.add_order(amount, self._clock.now())
        self._repository.save(user_to_record(user))
        return order

# Request parsing
@dataclass(frozen=True)
class UserRequest:
    user_id: str
    name: str
    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> UserRequest:
        if 'id' not in data:
            raise MissingUserIdError("User request requires 'id'")
        user_id = data['id']
        if not isinstance(user_id, str) or not user_id:
            raise MissingUserIdError("User 'id' must be a non-empty string")
        name = data.get('n', '')
        if not isinstance(name, str):
            raise InvalidRequestError("User 'n' must be a string")
        return cls(user_id, name)

@dataclass(frozen=True)
class OrderRequest:
    user_id: str
    amount: Decimal
    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> OrderRequest:
        user_id = data.get('uid')
        if not isinstance(user_id, str) or not user_id:
            raise MissingUserIdError("Order request requires 'uid'")
        amount = parse_amount(data.get('amt', 0))
        return cls(user_id, amount)

def parse_amount(value: Any) -> Decimal:
    try:
        if isinstance(value, Decimal): return value
        if isinstance(value, bool): raise InvalidOperation
        return Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError):
        raise InvalidAmountError("Order 'amt' must be a valid number")

# Commands
class Command(ABC):
    @abstractmethod
    def execute(self, raw: Mapping[str, Any]) -> str: ...

class CreateUserCommand(Command):
    def __init__(self, service: UserCreationService, logger: logging.Logger): ...
    def execute(self, raw):
        request = UserRequest.from_dict(raw)
        self._service.create(request.user_id, request.name)
        self._logger.info("Saved user")
        return "Saved user"

class AddOrderCommand(Command):
    def __init__(self, service: OrderService, logger): ...
    def execute(self, raw):
        request = OrderRequest.from_dict(raw)
        self._service.add_order(request.user_id, request.amount)
        self._logger.info("Saved order")
        return "Saved order"

# Router
class RequestRouter:
    def __init__(self, commands: Mapping[str, Command]):
        self._commands = dict(commands)
    def handle(self, raw: Mapping[str, Any]) -> str:
        if not isinstance(raw, Mapping):
            raise InvalidRequestError("Request must be a mapping")
        request_type = raw.get('t')
        command = self._commands.get(request_type)
        if command is None:
            raise UnknownRequestTypeError(f"Unknown request type: {request_type!r}")
        return command.execute(raw)

# Factory / composition root
def build_router(repository: UserRepository | None = None, clock: Clock | None = None, logger: logging.Logger | None = None) -> RequestRouter:
    repository = repository or InMemoryUserRepository()
    clock = clock or SystemClock()
    logger = logger or logging.getLogger(__name__)
    user_service = UserCreationService(repository, clock)
    order_service = OrderService(repository, clock)
    return RequestRouter({
       'user': CreateUserCommand(user_service, logger),
       'order': AddOrderCommand(order_service, logger),
    })

def handle(req: Mapping[str, Any]) -> str:
    return build_router().handle(req)

