class DomainError(Exception):
    """Base class for domain-level errors."""

class InvalidRequestError(DomainError):
    """Raised when a request payload is invalid."""

class UnknownRequestTypeError(InvalidRequestError):
    """Raised when the request type is not supported."""

class MissingUserIdError(InvalidRequestError):
    """Raised when a required user identifier is missing or empty."""

class InvalidAmountError(InvalidRequestError):
    """Raised when an order amount cannot be interpreted."""

class DuplicateUserError(DomainError):
    """Raised when creating a user that already exists."""

class UserNotFoundError(DomainError):
    """Raised when an operation references an unknown user."""

@dataclass(frozen=True)
class UserId:
    value: str

    def __post_init__(self) -> None:
        if not self.value:
            raise ValueError("User id must not be empty.")

@dataclass(frozen=True)
class Order:
    amount: Decimal
    created_at: float

class User:
    def __init__(self, user_id: UserId, name: str, created_at: float, orders: Optional[list[Order]] = None) -> None:
        self._id = user_id
        self._name = name
        self._created_at = created_at
        self._orders: list[Order] = list(orders or [])

    @property
    def id(self) -> UserId:
        return self._id

    @property
    def name(self) -> str:
        return self._name

    @property
    def created_at(self) -> float:
        return self._created_at

    @property
    def orders(self) -> tuple[Order, ...]:
        return tuple(self._orders)

    def add_order(self, amount: Decimal, created_at: float) -> Order:
        order = Order(amount, created_at)
        self._orders.append(order)
        return order

@dataclass
class OrderRecord:
    amount: Decimal
    created_at: float

@dataclass
class UserRecord:
    id: str
    name: str
    created_at: float
    orders: list[OrderRecord] = field(default_factory=list)

class UserRepository(ABC):
    @abstractmethod
    def exists(self, user_id: str) -> bool:
        ...
    @abstractmethod
    def get(self, user_id: str) -> Optional[UserRecord]:
        ...
    @abstractmethod
    def save(self, record: UserRecord) -> None:
        ...

class InMemoryUserRepository(UserRepository):
    def __init__(self) -> None:
        self._records: dict[str, UserRecord] = {}
        self._lock = threading.Lock()

    def exists(self, user_id: str) -> bool:
        with self._lock:
            return user_id in self._records

    def get(self, user_id: str) -> Optional[UserRecord]:
        with self._lock:
            record = self._records.get(user_id)
            return copy.deepcopy(record) if record is not None else None

    def save(self, record: UserRecord) -> None:
        with self._lock:
            self._records[record.id] = copy.deepcopy(record)

class Clock(ABC):
    @abstractmethod
    def now(self) -> float:
        ...

class SystemClock(Clock):
    def now(self) -> float:
        return time.time()

class UserMapper:
    def to_domain(self, record: UserRecord) -> User:
        return User(
            UserId(record.id),
            record.name,
            record.created_at,
            [Order(order.amount, order.created_at) for order in record.orders],
        )

    def to_record(self, user: User) -> UserRecord:
        return UserRecord(
            id=user.id.value,
            name=user.name,
            created_at=user.created_at,
            orders=[OrderRecord(order.amount, order.created_at) for order in user.orders],
        )

def parse_amount(value: Any) -> Decimal:
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, bool):
        raise InvalidAmountError("Order amount must be a number.")
    else:
        try:
            amount = Decimal(str(value))
        except (InvalidOperation, TypeError, ValueError):
            raise InvalidAmountError("Order amount must be a valid number.") from None
    if not amount.is_finite():
        raise InvalidAmountError("Order amount must be finite.")
    return amount

@dataclass(frozen=True)
class UserRequest:
    user_id: str
    name: str

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> UserRequest:
        if "id" not in data:
            raise MissingUserIdError("User request requires 'id'.")
        user_id = data["id"]
        if not isinstance(user_id, str) or not user_id:
            raise MissingUserIdError("User 'id' must be a non-empty string.")
        name = data.get("n", "")
        if name is None:
            name = ""
        if not isinstance(name, str):
            raise InvalidRequestError("User 'n' must be a string.")
        return cls(user_id=user_id, name=name)

@dataclass(frozen=True)
class OrderRequest:
    user_id: str
    amount: Decimal

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> OrderRequest:
        user_id = data.get("uid")
        if not isinstance(user_id, str) or not user_id:
            raise MissingUserIdError("Order request requires 'uid'.")
        return cls(user_id=user_id, amount=parse_amount(data.get("amt", 0)))

class Command(ABC):
    @abstractmethod
    def execute(self, raw: Mapping[str, Any]) -> str:
        ...

class CreateUserCommand(Command):
    def __init__(self, service: UserCreationService, logger: logging.Logger) -> None:
        self._service = service
        self._logger = logger

    def execute(self, raw: Mapping[str, Any]) -> str:
        request = UserRequest.from_dict(raw)
        self._service.create(request.user_id, request.name)
        self._logger.info("Saved user")
        return "Saved user"

class AddOrderCommand(Command):
    def __init__(self, service: OrderService, logger: logging.Logger) -> None:
        self._service = service
        self._logger = logger

    def execute(self, raw: Mapping[str, Any]) -> str:
        request = OrderRequest.from_dict(raw)
        self._service.add_order(request.user_id, request.amount)
        self._logger.info("Saved order")
        return "Saved order"

class UserCreationService:
    def __init__(self, repository: UserRepository, clock: Clock, mapper: UserMapper) -> None:
        self._repository = repository
        self._clock = clock
        self._mapper = mapper

    def create(self, user_id: str, name: str) -> User:
        if not user_id:
            raise MissingUserIdError("User id is required.")
        if self._repository.exists(user_id):
            raise DuplicateUserError(f"User '{user_id}' already exists.")
        user = User(UserId(user_id), name, self._clock.now())
        self._repository.save(self._mapper.to_record(user))
        return user

class OrderService:
    def __init__(self, repository: UserRepository, clock: Clock, mapper: UserMapper) -> None:
        self._repository = repository
        self._clock = clock
        self._mapper = mapper

    def add_order(self, user_id: str, amount: Decimal) -> Order:
        if not user_id:
            raise MissingUserIdError("User id is required.")
        record = self._repository.get(user_id)
        if record is None:
            raise UserNotFoundError(f"User '{user_id}' not found.")
        user = self._mapper.to_domain(record)
        order = user.add_order(amount, self._clock.now())
        self._repository.save(self._mapper.to_record(user))
        return order

class RequestRouter:
    def __init__(self, commands: Mapping[str, Command]) -> None:
        self._commands: dict[str, Command] = dict(commands)

    def handle(self, raw: Mapping[str, Any]) -> str:
        if not isinstance(raw, Mapping):
            raise InvalidRequestError("Request must be a mapping.")
        request_type = raw.get("t")
        command = self._commands.get(request_type)
        if command is None:
            raise UnknownRequestTypeError(f"Unknown request type: {request_type!r}.")
        return command.execute(raw)

class Application:
    def __init__(self, router: RequestRouter, logger: logging.Logger) -> None:
        self._router = router
        self._logger = logger

    def handle(self, raw: Mapping[str, Any]) -> str:
        try:
            return self._router.handle(raw)
        except DomainError as exc:
            self._logger.warning("Request failed: %s", exc)
            return f"Error: {exc}"
        except Exception:
            self._logger.exception("Unexpected error while handling request.")
            return "Error: Unexpected error"

def create_application(
    repository: Optional[UserRepository] = None,
    clock: Optional[Clock] = None,
    logger: Optional[logging.Logger] = None,
) -> Application:
    repository = repository or InMemoryUserRepository()
    clock = clock or SystemClock()
    logger = logger or logging.getLogger(__name__)
    mapper = UserMapper()
    user_service = UserCreationService(repository, clock, mapper)
    order_service = OrderService(repository, clock, mapper)
    router = RequestRouter(
        {
            "user": CreateUserCommand(user_service, logger),
            "order": AddOrderCommand(order_service, logger),
        }
    )
    return Application(router, logger)

_default_application = create_application()

def handle(req: Mapping[str, Any]) -> str:
    return _default_application.handle(req)
