```python
from __future__ import annotations

import time
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any


# ─── Domain Models ────────────────────────────────────────────────────────────

@dataclass
class Order:
    amount: float
    created: float = field(default_factory=time.time)


@dataclass
class User:
    id: str
    name: str = ""
    created: float = field(default_factory=time.time)
    orders: list[Order] = field(default_factory=list)


# ─── Domain Exceptions ────────────────────────────────────────────────────────

class DomainError(Exception):
    """Base for all domain-level errors."""


class UserAlreadyExistsError(DomainError):
    def __init__(self, user_id: str) -> None:
        super().__init__(f"User '{user_id}' already exists")
        self.user_id = user_id


class UserNotFoundError(DomainError):
    def __init__(self, user_id: str) -> None:
        super().__init__(f"User '{user_id}' not found")
        self.user_id = user_id


class InvalidRequestError(DomainError):
    pass


# ─── Persistence (Repository Abstraction) ────────────────────────────────────

class UserRepository(ABC):
    """Abstraction over user persistence – satisfies DIP."""

    @abstractmethod
    def get(self, user_id: str) -> User | None: ...

    @abstractmethod
    def save(self, user: User) -> None: ...

    @abstractmethod
    def exists(self, user_id: str) -> bool: ...


class InMemoryUserRepository(UserRepository):
    """Concrete in-memory store; swap for a DB-backed impl without touching services."""

    def __init__(self) -> None:
        self._store: dict[str, User] = {}

    def get(self, user_id: str) -> User | None:
        return self._store.get(user_id)

    def save(self, user: User) -> None:
        self._store[user.id] = user

    def exists(self, user_id: str) -> bool:
        return user_id in self._store


# ─── Application Services (Business Logic) ───────────────────────────────────

class UserService:
    def __init__(self, repo: UserRepository) -> None:
        self._repo = repo

    def create(self, user_id: str, name: str = "") -> User:
        if self._repo.exists(user_id):
            raise UserAlreadyExistsError(user_id)
        user = User(id=user_id, name=name)
        self._repo.save(user)
        return user


class OrderService:
    def __init__(self, repo: UserRepository) -> None:
        self._repo = repo

    def place(self, user_id: str, amount: float) -> Order:
        user = self._repo.get(user_id)
        if user is None:
            raise UserNotFoundError(user_id)
        order = Order(amount=amount)
        user.orders.append(order)
        self._repo.save(user)
        return order


# ─── Request Handling (Strategy + Open/Closed dispatch) ──────────────────────

@dataclass
class Request:
    type: str
    data: dict[str, Any]


class RequestHandler(ABC):
    """One handler per request type – new types are added, never modified (OCP)."""

    @abstractmethod
    def handle(self, req: Request) -> str: ...


class UserRequestHandler(RequestHandler):
    def __init__(self, service: UserService) -> None:
        self._service = service

    def handle(self, req: Request) -> str:
        user_id = req.data.get("id")
        if user_id is None:
            raise InvalidRequestError("Missing 'id' for user request")
        self._service.create(user_id, req.data.get("n", ""))
        return "Saved user"


class OrderRequestHandler(RequestHandler):
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle(self, req: Request) -> str:
        user_id = req.data.get("uid")
        if user_id is None:
            raise InvalidRequestError("Missing 'uid' for order request")
        self._service.place(user_id, float(req.data.get("amt", 0)))
        return "Saved order"


class Dispatcher:
    """Routes requests to the registered handler; extensible without modification."""

    def __init__(self) -> None:
        self._handlers: dict[str, RequestHandler] = {}

    def register(self, request_type: str, handler: RequestHandler) -> None:
        self._handlers[request_type] = handler

    def dispatch(self, req: Request) -> str:
        handler = self._handlers.get(req.type)
        if handler is None:
            raise InvalidRequestError(f"Unknown request type: '{req.type}'")
        return handler.handle(req)


# ─── Composition Root (Dependency Injection wiring) ──────────────────────────

def build_dispatcher(repo: UserRepository | None = None) -> Dispatcher:
    """Factory that wires the object graph. Callers can inject a custom repo."""
    if repo is None:
        repo = InMemoryUserRepository()

    user_service = UserService(repo)
    order_service = OrderService(repo)

    dispatcher = Dispatcher()
    dispatcher.register("user", UserRequestHandler(user_service))
    dispatcher.register("order", OrderRequestHandler(order_service))
    return dispatcher


# ─── Public Entry Point ───────────────────────────────────────────────────────

def handle(req: dict[str, Any], dispatcher: Dispatcher) -> str:
    """Thin adapter so existing callers pass a plain dict."""
    request = Request(type=req["t"], data=req)
    return dispatcher.dispatch(request)


# ─── Demo / Smoke Test ────────────────────────────────────────────────────────

if __name__ == "__main__":
    app = build_dispatcher()

    print(handle({"t": "user", "id": "u1", "n": "Alice"}, app))
    print(handle({"t": "order", "uid": "u1", "amt": 42.5}, app))
    print(handle({"t": "order", "uid": "u1", "amt": 10}, app))

    # Duplicate user → domain error
    try:
        handle({"t": "user", "id": "u1"}, app)
    except UserAlreadyExistsError as e:
        print(f"Caught: {e}")

    # Unknown user for order → domain error
    try:
        handle({"t": "order", "uid": "ghost", "amt": 1}, app)
    except UserNotFoundError as e:
        print(f"Caught: {e}")

    # Unknown type → domain error
    try:
        handle({"t": "coupon"}, app)
    except InvalidRequestError as e:
        print(f"Caught: {e}")
